import {queryLocal} from './assistant-read.mjs';
import {destinations,statusLabels,validatePlan,searchURL,favoriteOptions,matchObjects,commitAction} from './assistant-actions.mjs';
const $=id=>document.getElementById(id),read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}},FAVORITES='immobrain-listing-status-v1',SESSION='immobrain-calendar-session-v1';
const berlinDate=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function node(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n}
function refreshHome(){
 const today=berlinDate(),clock=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());
 $('today-label').textContent=new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Berlin'}).format(new Date());
 $('metric-objects').textContent=favoriteOptions(read(FAVORITES,{})).length;
 const views=read('immobrain-viewings-v1',[]),calcs=read('immobrain-fix-flip-saved-v1',[]);
 $('metric-checklists').textContent=Array.isArray(views)?views.length:0;$('metric-calcs').textContent=Array.isArray(calcs)?calcs.length:0;
 const events=CalendarEvents.build(localStorage,{includeNotes:false}).filter(e=>e.date>today||e.date===today&&(!e.time||e.time>=clock)).sort((a,b)=>(a.date+' '+(a.time||'00:00')).localeCompare(b.date+' '+(b.time||'00:00')));
 $('metric-visits').textContent=events.filter(e=>e.title.startsWith('Besichtigung')).length;
 const container=$('upcoming-list');container.replaceChildren();
 for(const event of events.slice(0,3)){const a=node('a',undefined,'upcoming-event');a.href=event.path;const day=node('div',undefined,'event-day');day.append(node('strong',event.date.slice(8)),node('small',new Intl.DateTimeFormat('de-DE',{month:'short',timeZone:'UTC'}).format(new Date(event.date+'T12:00:00Z'))));const copy=node('div');copy.append(node('h3',event.title),node('p',(event.time?event.time+' Uhr':'Ganztägig')+(event.location?' · '+event.location:'')));a.append(day,copy,node('span','↗'));container.append(a)}
 if(!events.length){const empty=node('div','Noch keine anstehenden Termine.','empty-state'),a=node('a','Eine Besichtigung planen →');a.href='/besichtigungskalender.html';empty.append(a);container.append(empty)}
}
let configured=false,pending=null;
function message(text){$('assistant-message').textContent=text}
function linkResult(label,href){const a=node('a',label,'button');a.href=href;return a}
function showPlan(raw){
 const plan=validatePlan(raw),result=$('assistant-result');result.replaceChildren();result.hidden=false;pending=plan;
 if(plan.action==='read'){const answer=queryLocal(localStorage,plan,CalendarEvents.build(localStorage,{includeNotes:false}));result.append(node('h3',answer.title),node('p',answer.text));for(const item of answer.items){const card=node('div');card.style.margin='12px 0';card.append(node('strong',item.title),node('p',item.detail),linkResult('Öffnen →',item.href));result.append(card)}if(answer.count>answer.items.length)result.append(linkResult('Weitere im Überblick →',['overview','object_details'].includes(plan.target)?destinations.objects:destinations.calendar));result.append(node('p','Quelle: gespeicherte Daten in diesem Browser.'));return}
 if(plan.action==='help'){result.append(node('p',plan.message||'Was möchtest du in ImmoBrain erledigen?'));return}
 if(plan.action==='navigate'){result.append(node('h3','Bereich öffnen'),linkResult('Jetzt öffnen →',destinations[plan.target]));return}
 if(plan.action==='search'){result.append(node('h3','Deine Suche ist vorbereitet'));const names={place:'Ort / PLZ',type:'Objektart',deal:'Vermarktung',price:'Maximalpreis',area:'Fläche ab',rooms:'Zimmer ab',sqm:'Preis pro m² bis'};for(const [key,value]of Object.entries(plan.filters))if(value!==undefined&&value!=='')result.append(node('p',names[key]+': '+String(value)+(key==='price'||key==='sqm'?' €':key==='area'?' m²':'')));result.append(node('p','Die Filter werden übernommen. Die Suche startest du auf der Suchseite.'),linkResult('Suchfilter übernehmen →',searchURL(plan.filters)));return}
 const options=favoriteOptions(read(FAVORITES,{})),matches=matchObjects(options,plan.objectQuery),list=matches.length?matches:options;
 result.append(node('h3',plan.action==='visit'?'Besichtigung prüfen & anlegen':'Objektstatus prüfen & ändern'));
 if(!options.length){result.append(node('p','Merke zuerst ein Objekt oder lege ein eigenes Objekt an.'),linkResult('Zu meinen Objekten →',destinations.objects));return}
 if(plan.objectQuery&&!matches.length)result.append(node('p','Kein eindeutiger Treffer für „'+plan.objectQuery+'“. Bitte das passende Objekt auswählen.'));
 const label=node('label','Objekt auswählen'),select=node('select');select.id='assistant-object';select.required=true;
 if(list.length!==1||!matches.length){const placeholder=node('option','Bitte auswählen');placeholder.value='';select.append(placeholder)}
 for(const option of list){const o=node('option',option.label);o.value=option.key;select.append(o)}label.append(select);result.append(label);
 let dateInput=null;
 if(plan.action==='visit'){result.append(node('p','Termin: '+plan.date.split('-').reverse().join('.')+' um '+plan.time+' Uhr · 60 Minuten'),node('p','Es wird eine neue, diesem Objekt zugeordnete Besichtigungs-Checkliste angelegt. Bestehende Termine bleiben erhalten.'))}
 else {result.append(node('p','Neuer Status: '+statusLabels[plan.status]));if(['angebot','besichtigt'].includes(plan.status)){const dateLabel=node('label',plan.status==='angebot'?'Angebot gestellt am':'Besichtigt am');dateInput=node('input');dateInput.type='date';dateInput.required=true;dateInput.max=berlinDate();dateInput.value=plan.date||berlinDate();dateLabel.append(dateInput);result.append(dateLabel)}}
 const actions=node('div',undefined,'result-actions'),save=node('button',plan.action==='visit'?'Besichtigung speichern':'Status speichern','button'),cancel=node('button','Abbrechen','plain-button');save.type=cancel.type='button';actions.append(save,cancel);result.append(actions);
 cancel.onclick=()=>{pending=null;result.hidden=true;message('Änderung verworfen.')};
 save.onclick=()=>{if(!select.value){select.focus();message('Bitte zuerst ein Objekt auswählen.');return}if(dateInput&&!dateInput.reportValidity())return;save.disabled=true;try{const action={...plan,date:dateInput?.value||plan.date};const saved=commitAction(localStorage,action,select.value,{costs:typeof ViewingData==='undefined'?[]:ViewingData.costs,today:berlinDate()});pending=null;result.replaceChildren(node('h3',saved.message),linkResult(plan.action==='visit'?'Zur Checkliste →':'Zum Objekt →',saved.href));message('Gespeichert.');refreshHome();window.dispatchEvent(new Event('immobrain-calendar-changed'));window.dispatchEvent(new Event('focus'))}catch(e){message(e.message||'Speicherung nicht möglich. Bitte Browserspeicher prüfen.');save.disabled=false}};
}
async function access(){let s;try{s=JSON.parse(sessionStorage.getItem(SESSION)||'null')}catch{}if(!s)throw Object.assign(Error('Bitte zuerst bei ImmoBrain anmelden.'),{signIn:true});if(s.expires_at<Date.now()/1000+60){const r=await fetch('https://ivatbtfjijqdbrmkvyvl.supabase.co/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:'sb_publishable_jBTlxVpS4_e4rIZI7eMAlA_BSRMJ1gM','Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token}),signal:AbortSignal.timeout(10000)});const d=await r.json();if(!r.ok||!d.access_token)throw Object.assign(Error('Deine Anmeldung ist abgelaufen. Bitte erneut anmelden.'),{signIn:true});s={...d,expires_at:Date.now()/1000+d.expires_in};sessionStorage.setItem(SESSION,JSON.stringify(s))}return s.access_token}
document.querySelectorAll('[data-prompt]').forEach(button=>button.addEventListener('click',()=>{$('assistant-input').value=button.dataset.prompt;$('assistant-input').focus()}));
$('assistant-form').onsubmit=async event=>{event.preventDefault();if(!configured)return;if(!$('assistant-form').reportValidity())return;const prompt=$('assistant-input').value.trim();if(!prompt)return;$('assistant-send').disabled=true;$('assistant-result').hidden=true;$('assistant-login').hidden=true;message('Deine Aktion wird vorbereitet …');try{const token=await access(),r=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({prompt}),signal:AbortSignal.timeout(40000)}),data=await r.json();if(!r.ok)throw Object.assign(Error(data.error||'Die Anfrage konnte nicht verarbeitet werden.'),{signIn:data.code==='sign_in'});showPlan(data.plan);message(data.plan.action==='read'?'Antwort aus deinen lokal gespeicherten Daten.':'Bitte den Vorschlag prüfen. Es wurde noch nichts gespeichert.')}catch(e){message(e.message||'Die Anfrage konnte nicht verarbeitet werden.');$('assistant-login').hidden=!e.signIn}finally{$('assistant-send').disabled=!configured}};
async function initAI(){try{const r=await fetch('/api/assistant/status',{cache:'no-store'}),d=await r.json();configured=r.ok&&d.configured===true;$('ai-state').textContent=configured?'KI bereit':'KI noch nicht aktiviert';$('assistant-send').disabled=!configured;message(configured?'Beschreibe deinen nächsten Schritt.':'Die freie KI-Eingabe ist vorbereitet; der API-Zugang muss noch aktiviert werden. Alle Schnellzugriffe auf dieser Seite kannst du bereits nutzen.')}catch{$('ai-state').textContent='KI nicht erreichbar';message('Die KI ist gerade nicht erreichbar. Nutze die Schnellzugriffe, um weiterzuarbeiten.')}}
refreshHome();initAI();window.addEventListener('storage',refreshHome);window.addEventListener('focus',refreshHome);setInterval(refreshHome,60000);
